compare.check:
(args, got) => {
      const { ops, args: a } = args;
      if (!Array.isArray(got) || got.length !== ops.length) return false;
      const bag = new Map();
      let total = 0, seen = new Map(), streak = 0;
      const endStreak = () => {
        let ok = true;
        if (streak >= 80 && total <= 6) for (const v of bag.keys()) if (!seen.has(v)) ok = false;
        if (streak >= 150) for (const [v, c] of bag) if (Math.abs((seen.get(v) || 0) / streak - c / total) > 0.2) ok = false;
        seen = new Map(); streak = 0;
        return ok;
      };
      for (let i = 0; i < ops.length; i++) {
        const op = ops[i], v = a[i][0];
        if (op === "RandomizedCollection") { if (got[i] !== null) return false; }
        else if (op === "insert") {
          if (got[i] !== !bag.has(v)) return false;
          if (!endStreak()) return false;
          bag.set(v, (bag.get(v) || 0) + 1); total++;
        } else if (op === "remove") {
          if (got[i] !== bag.has(v)) return false;
          if (bag.has(v)) {
            if (!endStreak()) return false;
            const c = bag.get(v) - 1;
            if (c === 0) bag.delete(v); else bag.set(v, c);
            total--;
          }
        } else if (op === "getRandom") {
          if (!bag.has(got[i])) return false;
          seen.set(got[i], (seen.get(got[i]) || 0) + 1); streak++;
        } else return false;
      }
      return endStreak();
    }
